import { Button, Descriptions, Input, List, Modal, Popover } from '@arco-design/web-react';
import { IconEdit, IconLanguage, IconPlus } from '@arco-design/web-react/icon';
import React, { useMemo, useState } from 'react';
import language from '@/store/language';
import styles from './index.module.less';

interface IconLanguageProps {
    value: string;
    readOnly?: boolean;
    onChange: (value: string) => void;
    trigger: any;
}
export default (props: IconLanguageProps) => {
    const [visible, setVisible] = useState<boolean>(false);
    const [value, setValue] = useState<string>("");

    const options = useMemo(() => {
        if(!value) return [];
        console.log('language.list', language.list)
        return language.list.filter((o) => o.input.indexOf(value) != -1)
    },[value])

    const listRender = useMemo(() => {
        if(!value) return null;
        return (
            <div className={styles.list}>
                <List
                    dataSource = {options}
                    render={(item) => {
                        return (
                            <List.Item className='cursor-pointer'
                                onClick={() => {
                                    if(props.onChange) props.onChange(item.key)
                                    setVisible(false);
                                }}
                            >
                                <Descriptions
                                    size="mini"
                                    colon="："
                                    layout='inline-horizontal'
                                    labelStyle={{ textAlign: 'right', fontWeight: "bold", paddingRight: 0, fontSize: 12 }}
                                    column={1}
                                    data={[
                                        {
                                            label: '多语言key',
                                            value: item.key
                                        },
                                        {
                                            label: '中文',
                                            value: item.zhCN
                                        },
                                        {
                                            label: '英文',
                                            value: item.enUS
                                        }
                                    ]}
                                />
                            </List.Item>
                        )
                    }}
                />
            </div>
        )
    },[value])
    
    const children = useMemo(() => {
        return (
            <div className={styles.iconLanguage}>
                <div className={styles.title}>
                    <span className={styles.titleText}>使用多语言</span>
                    {/* <IconPlus className={styles.icon} /> */}
                </div>
                <div className={styles.serch}>
                    <Input placeholder="请输入多语言Key"
                        value={value}
                        onChange={setValue}
                        // onPressEnter={onOk}
                    />
                    {/* <IconEdit className={styles.icon} /> */}
                </div>
                {listRender}
                <div className={styles.footer}>
                    {/* <Button 
                        style={{ marginRight: 8 }}
                        onClick={() => {
                            props.onChange('');
                        }}
                    >清空</Button>
                    <Button type="primary" size="small"
                        onClick={onOk}
                    >确认</Button> */}
                </div>
            </div>
        )
    },[value])

    return (
        <React.Fragment>
            <Popover 
                position="br"
                trigger="click"
                popupVisible={visible}
                onVisibleChange={(bool) => {
                    if(props.value){
                        setValue(props.value.replace(/(\$t\{)|\s|\}/g, ""));
                    }else {
                        setValue('');
                    }
                    setVisible(bool)
                }}
                style={{ width: 300 }}
                unmountOnExit
                content={children}
            >
                {props.trigger}
            </Popover>
        </React.Fragment>
    )
}